-- Hardening from the M2 review (docs/specs/m3-trading.md, "Before placeTrade writes ledger_entries").
-- The first four statements were generated by drizzle-kit from src/db/schema.ts (so the snapshot
-- matches); the privilege block after them is hand-written.

CREATE INDEX "ledger_entries_ref_idx" ON "ledger_entries" USING btree ("ref_type","ref_id");--> statement-breakpoint
CREATE INDEX "positions_user_id_idx" ON "positions" USING btree ("user_id");--> statement-breakpoint
CREATE INDEX "trades_market_id_idx" ON "trades" USING btree ("market_id");--> statement-breakpoint
ALTER TABLE "markets" ADD CONSTRAINT "markets_outcome_matches_status" CHECK (("markets"."status" in ('resolved', 'finalized')) = ("markets"."outcome" is not null));--> statement-breakpoint

-- Supabase's Data API roles get nothing in `public`, now or later. RLS deny-all (0001) already
-- hides every row; revoking the grants as well means a mistaken policy cannot expose a table.
-- Supabase grants these roles ALL on new objects by default; ALTER DEFAULT PRIVILEGES undoes that
-- for objects the migrating role creates from here on. The hook function keeps its own grants
-- (0002: only supabase_auth_admin may execute it). The roles exist on Supabase but not on PGlite
-- or a plain Postgres, hence the guards.
DO $$
DECLARE
  r text;
BEGIN
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM %I', r);
    END IF;
  END LOOP;
END
$$;
